 auto root=LibraryStore::root().getChildFile("favourite-display");root.createDirectory();auto file=root.getChildFile("Remote favourite.wav");AudioData audio;audio.rate=8000;audio.buffer.setSize(1,8000);audio.buffer.clear();require(PortableMedia526::writeWave(file,audio),"fixture");LibraryStore::addLibraryRoot(root);RackProcessor rack;auto& p=*rack.loops[0];p.autoSave=false;require(p.load(file),"load sample");Editor e(p,false);e.stopTimer();e.browserState->target=&e;e.directory=root;e.searchBranch=juce::File();e.search.setText({},false);e.folderSearch.setText({},false);e.activeTags.clear();e.excludedTags.clear();e.sampleTypeMask=e.colourFilterMask=0;e.favouriteFilter.setToggleState(false,juce::dontSendNotification);e.recursiveReady=true;e.recursiveRoot=root;
